# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, V, R, P, N = "Lucas", "Amparo", "Vicente", "Ramón", "Pepe", "Nuria"
D = [
("#", "Escena 1 · 8:00 · Sala de juntas, Onda", "장면 1 · 오전 8시 · 온다, 회의실"),
(None, "Lunes 28 de septiembre. Sobre la mesa, el dosier de Riad abierto en abanico: doscientas páginas en inglés, llenas de pósits amarillos. Lucas tiene ojeras. Nuria ha traído una caja de muestras y un termo de café.", "9월 28일 월요일. 탁자 위에 리야드에서 온 서류가 부채꼴로 펼쳐져 있다. 노란 포스트잇이 빼곡한 200쪽짜리 영어 서류다. 루카스는 눈 밑이 거뭇하다. 누리아는 샘플 상자 하나와 커피 보온병을 가져왔다."),
(R, "Por la cara que traes, Lucas, deduzco que el fin de semana te has leído el pliego entero.", "그 얼굴을 보니, 루카스, 주말 동안 사양서를 통째로 읽었나 보군."),
(L, "Entero no. Ciento ochenta páginas de doscientas. Las otras veinte son planos.", "통째로는 아니에요. 200쪽 중 180쪽이요. 나머지 20쪽은 도면이에요."),
(P, "¿Y la página ciento doce? La del vasco.", "112쪽은? 그 바스크 양반이 말한 거."),
(L, "Esa me la he leído tres veces. Y tenía razón: lo cambia todo. (abre el dosier) Os leo lo esencial, traducido. «La adjudicación se realizará por lotes. Cada licitador podrá presentar oferta a uno o varios lotes».", "그건 세 번 읽었어요. 그리고 그 사람 말이 맞았어요. 전부 바뀌어요. (서류를 펼치며) 핵심만 번역해서 읽어 줄게요. '낙찰은 로트별로 이루어진다. 각 응찰자는 하나 또는 여러 로트에 입찰할 수 있다.'"),
(V, "Eso ya nos lo dijo él por teléfono.", "그건 그 사람이 전화로 이미 말했잖아."),
(L, "Sí, pero hay más. El lote dos, viviendas, está dividido en tres sublotes por fases: 2A, 2B y 2C. Y se pueden ofertar por separado.", "네, 그런데 더 있어요. 2번 로트, 주거용은 단계별로 2A, 2B, 2C 세 개의 하위 로트로 나뉘어 있어요. 그리고 따로따로 입찰할 수 있어요."),
(R, "¿Cuánto es cada sublote?", "하위 로트는 각각 얼마야?"),
(L, "No son iguales. El 2B es la fase de las parcelas del norte: ciento doce mil quinientos metros cuadrados, en sesenta por ciento veinte y sesenta por sesenta. Seis mil doscientos cincuenta al mes durante dieciocho meses.", "똑같지 않아요. 2B는 북쪽 부지 단계예요. 11만 2,500㎡, 60×120과 60×60. 18개월 동안 매달 6,250㎡요."),
(P, "Seis mil doscientos cincuenta... (hace cuentas en una servilleta) Con los doce mil libres del tres, cabe. Pero entonces el tres se queda sin aire para nada más.", "6,250이라… (냅킨에 계산하며) 3호기에 남는 1만 2천이면 들어가긴 해. 그런데 그러면 3호기는 다른 건 숨 쉴 틈도 없어져."),
(L, "Y además están los vestíbulos. Lote uno: treinta mil metros de gran formato, mil setecientos al mes.", "거기에 로비도 있어요. 1번 로트, 대형 규격 3만㎡, 한 달에 1,700㎡요."),
(P, "Mil setecientos más seis mil doscientos cincuenta. Casi ocho mil. De doce mil libres. Y si un día se rompe un rodillo, ¿qué?", "1,700 더하기 6,250. 거의 8천. 남는 1만 2천 중에서. 그러다 어느 날 롤러가 하나 부러지면, 그땐?"),
(R, "Esa es la pregunta. Sigue leyendo, Lucas. ¿Cómo evalúan?", "그게 문제야. 계속 읽어, 루카스. 평가는 어떻게 한대?"),
(L, "«Se valorará en un sesenta por ciento la oferta técnica y en un cuarenta por ciento la oferta económica». O sea, que el precio no lo es todo.", "'기술 제안서를 60%, 가격 제안서를 40%로 평가한다.' 그러니까 가격이 전부가 아니라는 거예요."),
(N, "¿Y qué entra en lo técnico?", "기술 쪽엔 뭐가 들어가요?"),
(L, "Muestras, certificados, capacidad de producción demostrada, plan de entregas, asistencia en obra... y el diseño de los vestíbulos.", "샘플, 인증서, 입증된 생산 능력, 납품 계획, 현장 지원… 그리고 로비 디자인이요."),
(N, "(abre su caja) Eso me gusta más. Mirad. Lo empecé el sábado.", "(상자를 열며) 그건 좀 더 마음에 드네요. 봐요. 토요일에 시작했어요."),
(None, "Nuria saca una pieza de prueba de color arena, con vetas suaves de tono ocre y gris, como piedra de desierto pulida por el viento.", "누리아가 모래색 시험용 타일 하나를 꺼낸다. 황토색과 회색의 부드러운 결이 바람에 닳은 사막 돌 같다."),
(V, "Qué bonita. Parece piedra de verdad.", "예쁘구나. 진짜 돌 같네."),
(N, "Se llama «Arena de Najd». Najd es la meseta central de Arabia, donde está Riad. He mirado fotos de las montañas de alrededor: tienen estos colores al atardecer.", "'아레나 데 나즈드'라고 해요. 나즈드는 리야드가 있는 아라비아 중부 고원이에요. 주변 산 사진을 찾아봤는데, 해 질 녘에 이런 색이에요."),
(A, "Eso es lo que nos funcionó en Monterrey. Blanco San Pedro, con el cerro escondido en la veta.", "그게 몬테레이에서 통했던 방식이에요. 블랑코 산페드로, 결 속에 산을 숨긴 거요."),
(P, "Bonita es. Pero ¿en qué formato? Porque el pliego habla de vestíbulos de hotel.", "예쁘긴 하네. 그런데 규격은? 사양서에는 호텔 로비라고 되어 있잖아."),
(L, "Ciento veinte por doscientos sesenta, como el de Monterrey. Y piden también placas de ciento sesenta por trescientos veinte para las paredes.", "120×260, 몬테레이 것과 같아요. 그리고 벽용으로 160×320 판도 요구해요."),
(P, "Las de tres metros veinte las hemos hecho tres veces en la vida. Y dos salieron bien.", "3미터 20짜리는 평생 세 번 만들어 봤어. 그중 두 번 잘 나왔지."),
(N, "Por eso el dibujo tiene que perdonar. Si la veta es suave, una diferencia mínima de tono no se nota entre una placa y la de al lado.", "그래서 무늬가 너그러워야 해요. 결이 부드러우면 판과 판 사이에 아주 작은 색조 차이가 있어도 티가 안 나요."),
(A, "Y la arena tiene una ventaja: el polvo del desierto se ve menos sobre un beige que sobre un blanco.", "그리고 모래색엔 장점이 하나 있어요. 사막 먼지는 흰색보다 베이지색 위에서 덜 보여요."),
(N, "Eso no lo había pensado. Me lo apunto para la memoria técnica.", "그건 생각 못 했어요. 기술 제안서에 넣게 적어 둘게요."),
(R, "Lo bonito no paga el aval. Hablemos de dinero. ¿Cuánto es el aval?", "예쁜 걸로 보증금이 나오진 않아. 돈 얘기 하자. 보증금은 얼마야?"),
(L, "El dos por ciento del valor de la oferta de cada lote. Si ofertamos el lote uno a treinta y cuatro euros el metro, CIF Dammam, son un millón veinte mil euros. El aval, veinte mil cuatrocientos.", "로트마다 입찰 금액의 2%예요. 1번 로트를 담맘항 도착 기준 ㎡당 34유로로 내면 102만 유로예요. 보증금은 2만 400유로."),
(R, "¿Treinta y cuatro? ¿De dónde sale ese número?", "34? 그 숫자는 어디서 나왔어?"),
(L, "De México. El vestíbulo de Monterrey lo vendimos a treinta y ocho cincuenta puesto en destino. Aquí el flete es más barato y el volumen es quince veces mayor. Por eso un poco menos.", "멕시코에서요. 몬테레이 로비는 도착지 인도 조건으로 38.50유로에 팔았어요. 여긴 운임이 더 싸고 물량은 열다섯 배예요. 그래서 조금 낮게요."),
(R, "Bien razonado. ¿Y el 2B?", "논리는 괜찮네. 2B는?"),
(L, "Ahí está el problema. Es vivienda, y en vivienda compiten los chinos y los indios. Si ofertáramos a precio de lista, no tendríamos ninguna posibilidad.", "거기가 문제예요. 주거용이라 중국, 인도 업체들이 경쟁해요. 정가로 입찰하면 가능성이 전혀 없을 거예요."),
(R, "Pues mi suelo no se mueve. Doce cincuenta en fábrica. Trece veinte puesto en el barco en Valencia. Y el flete hasta Dammam...", "그래도 내 하한선은 안 움직여. 공장 출고 12.50. 발렌시아에서 배에 실으면 13.20. 그리고 담맘까지 운임이…"),
(L, "Uno sesenta, según Jordi. O sea, catorce ochenta CIF como mínimo absoluto. Yo propondría quince cuarenta.", "조르디 말로는 1.60이에요. 그러니까 CIF 기준 절대 최저가 14.80이죠. 저는 15.40을 제안하고 싶어요."),
(R, "Quince cuarenta por ciento doce mil quinientos metros... un millón setecientos treinta y dos mil quinientos. Aval: treinta y cuatro mil seiscientos cincuenta.", "15.40 곱하기 11만 2,500㎡… 173만 2,500유로. 보증금은 3만 4,650유로."),
(V, "Entre los dos, unos cincuenta y cinco mil euros de aval.", "둘을 합치면 보증금이 5만 5천 유로쯤이군."),
(R, "Mucho menos que ciento treinta mil. Eso sí, son cincuenta y cinco mil que el banco nos descuenta de la póliza mientras dure la licitación.", "13만보다는 훨씬 적지. 다만 입찰이 진행되는 동안 은행이 그 5만 5천을 우리 한도에서 묶어 둬."),
(A, "¿Y el lote tres? Exteriores.", "3번 로트는요? 외부용이요."),
(L, "Cincuenta mil metros de exterior, antideslizante, para plazas y piscinas. Lo he mirado. Piden un espesor de dos centímetros. No lo fabricamos.", "외부용 5만㎡, 미끄럼 방지, 광장과 수영장용이에요. 찾아봤어요. 두께 2센티미터를 요구해요. 우리는 안 만들어요."),
(P, "Ni lo vamos a fabricar este año. Fuera.", "올해 안에 만들 일도 없고. 빼."),
(V, "Fuera el tres. Quedan el uno y el 2B. Pepe, la pregunta de verdad: ¿podemos?", "3번은 빼고. 1번과 2B가 남았군. 페페, 진짜 질문이야. 할 수 있나?"),
(P, "El uno, sí. El 2B, con el tres solo, no. Si os empeñáis, necesitamos más horno.", "1번은 돼요. 2B는 3호기 하나로는 안 돼요. 꼭 하겠다면 가마가 더 필요해요."),
(L, "Tengo dos ideas. Las digo y luego me pegáis.", "아이디어가 두 개 있어요. 말할 테니 그다음에 때리세요."),
(R, "Di.", "말해."),
(L, "Una: el horno uno. Hoy hace como mucho sesenta por sesenta y está lleno de pedidos nacionales. Si lo reformáramos para que hiciera sesenta por ciento veinte, ¿cuánto sacaría?", "하나. 1호기요. 지금은 최대 60×60까지만 하고 국내 주문으로 차 있어요. 60×120을 만들 수 있게 개조하면 얼마나 나올까요?"),
(P, "(se rasca la cabeza) Alargarlo, quemadores nuevos, otra entrada de prensa... Unos quince mil al mes. Pero eso es dinero, y seis semanas parado.", "(머리를 긁으며) 길이를 늘리고, 버너를 새로 달고, 프레스 투입구를 바꾸고… 한 달에 1만 5천쯤. 하지만 그건 돈이 들고, 6주는 세워야 해."),
(R, "¿Cuánto dinero?", "돈은 얼마나?"),
(P, "No lo sé. Llamo al fabricante esta semana. Pero no penséis en cifras pequeñas.", "몰라요. 이번 주에 제조사에 전화해 볼게요. 하지만 작은 숫자는 생각하지 마세요."),
(L, "Dos: mientras el uno está parado, alguien nos ayuda. Monfort tiene un horno de rodillos medio vacío desde el verano. Lo sé por Paco.", "둘. 1호기가 서 있는 동안 누가 우리를 도와주는 거예요. 몬포르트에 여름부터 반쯤 비어 있는 롤러 가마가 있어요. 파코한테 들었어요."),
(None, "Silencio. Vicente deja la taza en el plato con más fuerza de la necesaria.", "침묵. 비센테가 필요 이상으로 세게 잔을 받침에 내려놓는다."),
(V, "¿Monfort? ¿Rafa Monfort?", "몬포르트? 라파 몬포르트?"),
(L, "¿Hay otro?", "다른 몬포르트가 있어요?"),
(P, "No. Por desgracia, no hay otro.", "없지. 불행히도 하나뿐이야."),
(L, "¿Qué tiene de malo Monfort?", "몬포르트가 뭐가 문제예요?"),
(P, "Lo de Rafa te lo contará otro. Lo mío es más simple. Y aunque hubiera otro Monfort, Lucas: yo no controlo el horno de otro. Si Monfort hace una tanda con otro tono y la mandamos a Riad con nuestro nombre, el que queda mal soy yo.", "그리고 다른 사람이 있다 해도, 루카스, 난 남의 가마를 통제 못 해. 몬포르트가 다른 색조로 한 번 구워서 그게 우리 이름으로 리야드에 가면, 망신당하는 건 나야."),
(R, "Y yo no firmo un aval para que otro fabrique. El riesgo es nuestro y la fábrica es suya.", "그리고 난 남이 만들게 하려고 보증서에 서명하지 않아. 위험은 우리 거고 공장은 그 사람 거잖아."),
(L, "Lo entiendo. Por eso no sería «fabricad vosotros y ya está». Sería con nuestra calidad: Maribel en su línea, nuestros lotes, nuestras etiquetas.", "알아요. 그래서 '너희가 만들어, 끝' 식이 아니라는 거예요. 우리 품질로요. 마리벨이 그쪽 라인에 가고, 우리 로트, 우리 라벨로요."),
(N, "Técnicamente se puede. Le paso las fórmulas de esmalte, las tramas digitales...", "기술적으로는 가능해요. 유약 배합이랑 디지털 패턴을 넘겨주면…"),
(V, "¿Las fórmulas? ¿A Monfort?", "배합을? 몬포르트한테?"),
(A, "Papá. Respira.", "아빠. 숨 쉬어요."),
(V, "Respiro. Pero dejadme decir una cosa: el hecho de que necesitemos a Rafa no significa que me guste.", "쉬고 있어. 하지만 하나만 말하게 해 줘. 우리가 라파를 필요로 한다는 사실이 내가 그걸 좋아한다는 뜻은 아니야."),
(L, "Nadie ha dicho que tenga que gustarte. Solo que tiene que funcionar.", "좋아해야 한다고는 아무도 안 했어요. 돌아가기만 하면 된다는 거죠."),
(R, "Lucas, déjame poner las cartas sobre la mesa. El jueves dije: un año sin nuevos mercados. Hoy estamos hablando de reformar un horno y de fabricar en casa del vecino. En cuatro días.", "루카스, 패를 다 까 놓고 말할게. 목요일에 난 1년 동안 새 시장은 없다고 했어. 오늘 우리는 가마를 개조하고 옆집에서 생산하는 얘기를 하고 있어. 나흘 만에."),
(L, "Lo sé. Y si dentro de una semana los números no salen, seré el primero en decir que solo vamos al lote uno.", "알아요. 그리고 일주일 뒤에 숫자가 안 나오면, 1번 로트만 가자고 제일 먼저 말할게요."),
(R, "Que conste en acta.", "회의록에 남겨."),
(A, "Consta. Por delante y por detrás.", "남겼어요. 앞면에도, 뒷면에도."),
(N, "¿Y lo de las etiquetas? He visto un pósit que pone «árabe».", "라벨은요? '아랍어'라고 쓰인 포스트잇을 봤는데요."),
(L, "Sí. Todas las cajas, con etiqueta en árabe e inglés. Y el certificado de conformidad, a través de una plataforma saudí que se llama SABER, conforme a sus normas, las SASO.", "네. 모든 상자에 아랍어와 영어 라벨이요. 그리고 적합성 인증서는 SABER라는 사우디 플랫폼을 통해서 받아야 해요. 그쪽 규격인 SASO에 맞게요."),
(A, "¿Y el embalaje? Allí los palés estarán al sol semanas enteras.", "포장은요? 거기선 팔레트가 몇 주씩 햇볕에 놓여 있을 텐데요."),
(L, "Lo dice la página ciento cuarenta: film con protección ultravioleta, palés tratados según la norma internacional, y cajas que aguanten cincuenta grados sin deformarse.", "140쪽에 있어요. 자외선 차단 필름, 국제 규격에 따라 처리된 팔레트, 그리고 50도에서도 변형되지 않는 상자요."),
(A, "Cincuenta grados. Eso es química. El cartón, la cola, la tinta de la etiqueta... Me apunto.", "50도라. 그건 화학이에요. 상자 판지, 접착제, 라벨 잉크… 내가 맡을게요."),
(R, "¿Algo más que nos vaya a costar dinero?", "돈이 더 들어갈 일 또 있어?"),
(L, "Las penalizaciones. «En caso de retraso en las entregas, se aplicará una penalización del medio por ciento del valor del pedido por cada semana de retraso».", "위약금이요. '납품이 지연될 경우 지연 1주마다 주문 금액의 0.5%를 위약금으로 부과한다.'"),
(P, "Medio por ciento a la semana. Con un rodillo roto, en un mes nos comemos el margen.", "일주일에 0.5%라. 롤러 하나 부러지면 한 달 만에 마진이 날아가겠네."),
(V, "Por eso he dicho: a lo que podamos cumplir. Ni un metro más.", "그래서 내가 말했잖아. 우리가 지킬 수 있는 만큼. 1㎡도 더는 안 된다고."),

("#", "Escena 2 · 13:40 · Oficina de exportación", "장면 2 · 오후 1시 40분 · 수출팀 사무실"),
(None, "Amparo cierra la puerta. En la pared, el mapa: Monterrey, Miami y, en Bogotá, una chincheta verde que todavía no es de ningún color definitivo.", "암파로가 문을 닫는다. 벽에 지도가 있다. 몬테레이, 마이애미, 그리고 보고타에는 아직 확정되지 않은 초록 압정 하나."),
(A, "Tenemos un problema que no ha salido en la reunión.", "회의에서 안 나온 문제가 하나 있어요."),
(L, "Bogotá.", "보고타."),
(A, "Bogotá. Camilo ha confirmado la visita técnica: martes trece y miércoles catorce de octubre. Y la oferta de Riad se entrega el dieciséis.", "보고타요. 카밀로가 기술 방문 날짜를 확정했어요. 10월 13일 화요일과 14일 수요일. 그리고 리야드 입찰서는 16일에 내야 하고요."),
(L, "¿No se puede mover?", "옮길 수는 없어요?"),
(A, "Se lo he preguntado. La clínica decide a finales de octubre y visitan a los tres finalistas esa semana. Si no voy, es como si no nos presentáramos.", "물어봤어요. 클리닉은 10월 말에 결정하고, 그 주에 최종 후보 세 곳을 다 방문해요. 내가 안 가면 우리가 응찰하지 않은 거나 마찬가지예요."),
(L, "Entonces vas.", "그럼 가요."),
(A, "¿Así de fácil? Hace un mes me dijiste que no firmara nada sola. Y ahora te voy a dejar solo con un pliego de doscientas páginas.", "그렇게 간단하게? 한 달 전에 혼자서는 아무것도 서명하지 말라고 했잖아요. 그런데 이제 200쪽짜리 사양서랑 당신을 혼자 두게 생겼는데요."),
(L, "Eso me lo dijiste tú a mí, en Atlanta. Ni una servilleta.", "그건 애틀랜타에서 당신이 나한테 한 말이에요. 냅킨 한 장도 안 된다고."),
(A, "(sonríe) Es verdad. Bueno, da igual quién lo dijera. El pacto es el pacto.", "(웃으며) 맞네요. 뭐, 누가 말했든 상관없어요. 약속은 약속이니까."),
(L, "Pues lo cumplimos. Nos repartimos el trabajo antes de que te vayas, y cada noche nos llamamos. Como en Houston.", "그럼 지키면 되죠. 당신이 떠나기 전에 일을 나누고, 매일 밤 통화해요. 휴스턴 때처럼."),
(A, "¿Qué me quedo yo?", "나는 뭘 맡아요?"),
(L, "Todo lo químico: el embalaje para los cincuenta grados, la tinta de las etiquetas, y el expediente técnico de las muestras. Lo que digas tú, va a misa.", "화학 쪽 전부요. 50도용 포장, 라벨 잉크, 그리고 샘플의 기술 서류. 당신이 하는 말이 곧 법이에요."),
(A, "¿Y tú?", "당신은요?"),
(L, "Los números con Ramón, el banco, Monfort... y la parte de Madrid, si Iñaki nos manda a hablar con su empresa.", "라몬이랑 숫자, 은행, 몬포르트… 그리고 이냐키가 자기 회사와 얘기해 보라고 하면 마드리드 쪽도요."),
(A, "Monfort contigo y con mi padre. A solas no. Mi padre y Rafa a solas son como el gas y una cerilla.", "몬포르트는 당신이랑 아빠가 같이 가요. 둘만 보내면 안 돼요. 아빠랑 라파 둘만 있으면 가스랑 성냥이에요."),
(L, "¿Qué pasó entre ellos? Nadie me lo cuenta.", "두 사람 사이에 무슨 일이 있었어요? 아무도 얘기를 안 해 줘요."),
(A, "En dos mil nueve, cuando lo de Guadalajara, mi padre tuvo que vender una prensa para pagar nóminas. La compró Rafa. Barata. Muy barata. Y luego fue diciendo por Onda que la había comprado «de rebajas».", "2009년, 과달라하라 일 때, 아빠는 월급을 주려고 프레스 한 대를 팔아야 했어요. 그걸 라파가 샀어요. 싸게. 아주 싸게. 그러고는 온다를 돌아다니면서 '할인 매대에서' 샀다고 말하고 다녔고요."),
(L, "Ah. Ya.", "아. 그렇군요."),
(A, "Rafa no es mala persona. Pero tiene la lengua más rápida que la cabeza. Y mi padre tiene memoria de elefante.", "라파가 나쁜 사람은 아니에요. 하지만 머리보다 혀가 빨라요. 그리고 아빠는 기억력이 코끼리고요."),
(L, "Entonces la reunión con Monfort la preparo como si fuera con un cliente difícil.", "그럼 몬포르트와의 미팅은 까다로운 고객을 만나는 것처럼 준비할게요."),
(A, "Prepárala como si fuera con tu suegro. Es peor.", "장인어른 만나는 것처럼 준비해요. 그게 더 힘들어요."),

("#", "Escena 3 · 18:30 · Despacho de Vicente", "장면 3 · 오후 6시 30분 · 비센테의 사무실"),
(None, "Por la ventana se ve la nave del horno tres, con el humo blanco de las chimeneas. Vicente tiene el dosier cerrado delante. Entran Lucas, Ramón y Pepe.", "창밖으로 3호기 작업동과 굴뚝의 흰 연기가 보인다. 비센테 앞에는 서류가 덮여 있다. 루카스, 라몬, 페페가 들어온다."),
(V, "Os he llamado antes del lunes que dije. No quiero esperar una semana dándole vueltas. Ramón, tú primero.", "내가 말한 월요일보다 먼저 불렀어. 일주일 내내 머리 싸매고 기다리고 싶지 않아서. 라몬, 자네 먼저."),
(R, "El lote uno, sí. Los números salen, el aval es razonable y el riesgo es pequeño. El 2B... depende de dos cosas que hoy no sabemos: cuánto cuesta el horno uno y qué pide Monfort.", "1번 로트는 찬성. 숫자가 나오고, 보증금도 합리적이고, 위험도 작아. 2B는… 오늘은 모르는 두 가지에 달렸어. 1호기 개조 비용, 그리고 몬포르트가 뭘 요구하는지."),
(V, "Pepe.", "페페."),
(P, "El uno, sí. El 2B, solo si me dejáis poner a Maribel en la línea de Monfort desde el primer día. Y si el horno uno se reforma bien, no deprisa.", "1번은 찬성. 2B는 첫날부터 마리벨을 몬포르트 라인에 둘 수 있을 때만요. 그리고 1호기는 빨리가 아니라 제대로 개조해야 해요."),
(V, "Lucas.", "루카스."),
(L, "El uno, sí. El 2B, también, pero con una condición mía: si dentro de una semana no tenemos el presupuesto del horno y un sí de Monfort por escrito, no ofertamos el 2B. Sin dramas.", "1번은 찬성이요. 2B도 찬성인데 제 조건이 하나 있어요. 일주일 안에 가마 견적과 몬포르트의 서면 동의를 못 받으면 2B는 입찰하지 않아요. 미련 없이."),
(V, "¿Y Amparo?", "암파로는?"),
(L, "Amparo se va a Bogotá el diez. Lo hemos hablado. Se queda con el embalaje y el expediente técnico, y me llama cada noche.", "암파로는 10일에 보고타로 가요. 같이 얘기했어요. 포장이랑 기술 서류를 맡고, 매일 밤 전화하기로 했어요."),
(V, "(asiente despacio) Bien. Entonces lo decido así: lote uno, adelante. 2B, tenéis una semana para hablar con Monfort y con el fabricante del horno. El lote tres, fuera.", "(천천히 고개를 끄덕이며) 좋아. 그럼 이렇게 결정하지. 1번 로트는 진행. 2B는 일주일 안에 몬포르트와 가마 제조사와 얘기해 봐. 3번 로트는 빼고."),
(R, "¿Y quién habla con Monfort?", "몬포르트하고는 누가 얘기해?"),
(V, "Lucas. Y yo voy con él.", "루카스. 그리고 나도 같이 가."),
(P, "(levanta las cejas) ¿Tú? ¿A casa de Rafa?", "(눈썹을 치켜올리며) 사장님이요? 라파네 집에?"),
(V, "Si mi hija va sola a Bogotá, yo puedo ir a cuatro kilómetros de aquí. Aunque fuera la última fábrica de Castellón.", "내 딸이 혼자 보고타에 가는데, 난 여기서 4킬로미터 떨어진 데쯤은 갈 수 있지. 거기가 카스테욘의 마지막 공장이라 해도."),
(L, "Gracias, Vicente.", "고마워요, 비센테."),
(V, "No me des las gracias. Prométeme una cosa: si Rafa dice lo de las rebajas, me sacas de allí antes de que conteste.", "고맙단 말은 하지 마. 대신 하나만 약속해. 라파가 할인 매대 얘기를 꺼내면, 내가 대꾸하기 전에 날 거기서 끌고 나와."),
(L, "Prometido.", "약속해요."),
(R, "Yo mañana llamo a la señora Navarro por los avales. Si vamos a correr, que el banco corra con nosotros.", "난 내일 나바로 씨한테 보증서 건으로 전화할게. 우리가 뛸 거면 은행도 같이 뛰어야지."),
(P, "Y yo llamo al del horno. Aunque os aviso: los fabricantes de hornos hablan como los médicos. Primero te asustan y luego te cobran.", "그리고 난 가마 쪽에 전화할게요. 미리 말하지만, 가마 제조사들은 의사처럼 말해요. 먼저 겁을 주고, 그다음에 돈을 받죠."),
(V, "(ríe por primera vez en todo el día) Pues que nos asusten poco.", "(하루 만에 처음으로 웃으며) 그럼 조금만 겁주라고 해."),
(L, "Hagamos el calendario ahora, que si no se nos escapa. Jueves uno, banco. Lunes cinco, Monfort.", "지금 일정을 짜요. 안 그러면 놓쳐요. 1일 목요일, 은행. 5일 월요일, 몬포르트."),
(R, "¿Y las muestras? Tienen que estar en Riad antes del dieciséis.", "샘플은? 16일 전에 리야드에 있어야 하잖아."),
(P, "Si Nuria me da el diseño el miércoles, las cuezo el lunes cinco en el tres. Pero solo una tanda. No me pidáis dos.", "누리아가 수요일에 디자인을 주면 5일 월요일에 3호기에서 구울게. 하지만 딱 한 번이야. 두 번은 요구하지 마."),
(L, "Una tanda. Y el viernes nueve, el mensajero. Con el certificado, o sin muestras no hay oferta.", "한 번. 그리고 9일 금요일엔 특송. 인증서도 같이요. 안 그러면 샘플이 없어서 입찰도 못 해요."),
(R, "Y el quince, la oferta subida a su portal. Un día antes, que nunca me fío de las páginas web.", "그리고 15일엔 그쪽 포털에 입찰서 업로드. 하루 일찍. 난 웹사이트를 절대 안 믿거든."),
(V, "Tres semanas, cinco fechas. Esto parece la Magdalena: todo el mundo corriendo y nadie sabe si llueve.", "3주에 날짜가 다섯 개라. 꼭 마그달레나 같네. 다들 뛰어다니고, 비가 올지는 아무도 몰라."),
(None, "Lucas se queda un momento solo en el pasillo. Abre el dosier por la página ciento doce y escribe al margen, a lápiz: «Lote 1 + 2B. Una semana».", "루카스는 복도에 잠시 혼자 남는다. 서류의 112쪽을 펼치고 여백에 연필로 적는다. '1번 + 2B. 일주일.'"),
(L, "(para sí) Tres semanas para todo. Una para decidir. Y un vecino que compra prensas de rebajas.", "(혼잣말로) 전부 해서 3주. 결정하는 데 일주일. 그리고 프레스를 할인 매대에서 사는 이웃 하나."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "9월 28일 월요일, 온다. 주말 동안 200쪽짜리 사양서를 읽은 루카스가 112쪽의 비밀을 풀어놓는다. 2번 로트(주거)가 세 개의 하위 로트로 나뉘어 있어서 그중 하나인 2B만 입찰할 수 있다는 것이다. 누리아는 사우디용 새 디자인 '아레나 데 나즈드'를 들고 오고, 라몬은 보증금을 계산하고, 페페는 가마의 한계를 경고한다. 루카스가 1호기 개조와 이웃 회사 몬포르트와의 협업을 꺼내자 비센테의 얼굴이 굳는다. 오후에는 암파로가 보고타 출장과 입찰 마감이 겹친다는 문제를 꺼낸다.",
 "듣기 질문 ① 사양서는 기술과 가격을 각각 몇 퍼센트로 평가하는가? 1번 로트와 2B의 입찰가와 보증금은 각각 얼마인가?",
 "듣기 질문 ② 루카스가 2B를 위해 낸 두 가지 아이디어는 무엇이고, 페페와 라몬은 각각 왜 반대하는가?",
 "듣기 질문 ③ 비센테와 라파 몬포르트 사이에는 2009년에 무슨 일이 있었는가? 비센테는 최종적으로 무엇을 결정하는가?",
]),
]

